from rwkv_lh import task_review as v
D=R/'data/experiments/RWKV_SINGLE_EDIT_BASELINE_R1_20260913'
def save(p,x):p.parent.mkdir(parents=True,exist_ok=True);p.write_text(json.dumps(x,ensure_ascii=False,indent=2)+'\n')
def snapshot(src,dst):shutil.copytree(src,dst,symlinks=True)
class RecordedHarness(ActionHarness):
 def __init__(self,output):super().__init__();self.output=output;self.index=0
 def execute(self,action,goal):
  self.index+=1;p=self.output/'tool_snapshots'/f'{self.index:03d}';p.mkdir(parents=True);snapshot(Path(goal.workspace_root),p/'before')
  save(p/'call.json',{'action_type':action.action_type,'arguments':action.arguments})
  try:return super().execute(action,goal)
  finally:snapshot(Path(goal.workspace_root),p/'after')
def run(job,settings):
 output=Path(job['output_dir']);output.mkdir(parents=True,exist_ok=False);workspace=Path(job['workspace']);snapshot(workspace,output/'initial_workspace');records=[];errors=[];state=None;store=None;error=None;termination=None;started=time.monotonic();trace=output/'model_trace.jsonl';trace.touch()
 def audit(event):
  records.append(dict(event))
  try:
   with trace.open('a') as f:f.write(json.dumps(dict(event),ensure_ascii=False)+'\n')
  except Exception as exc:errors.append(str(exc));raise
 def deadline(*_):raise _WallDeadlineExpired('wall budget exhausted')
 old=signal.signal(signal.SIGALRM,deadline);signal.setitimer(signal.ITIMER_REAL,job['max_seconds'])
 try:
  harness=RecordedHarness(output);model=LongHorizonModel(create_model_session(settings=settings,audit_hook=audit),harness=harness);model.session=_BudgetedSession(model.session,job['max_calls'],started+job['max_seconds'],errors)
  store=LongHorizonStore(output/'state',checkpoint_retention=1000);goal=model.create_literal_goal(job['request'],str(workspace),runtime_policy={RUN_LIFECYCLE_POLICY_KEY:run_lifecycle_policy_document('goal')});state=store.create_run(goal,run_id=job['task_id']);save(output/'goal.json',goal.to_dict())
  LongHorizonController(store,model=model,harness=harness,max_transitions=job['max_calls'],min_actions=0).run(state.run_id)
 except (Exception,_WallDeadlineExpired) as exc:
  termination='budget' if isinstance(exc,(ReadOnlyBudgetExpired,_WallDeadlineExpired)) else 'error';error={'type':type(exc).__name__,'message':str(exc),'traceback':traceback.format_exc()}
 finally:signal.setitimer(signal.ITIMER_REAL,0);signal.signal(signal.SIGALRM,old)
 if state is not None:state=store.load(state.run_id)
 result={'id':job['task_id'],'final':(state.final_output or None) if state else None,'termination':termination or ('submitted' if state and state.status==RunStatus.COMPLETED else 'budget'),'acceptance':'not_evaluated' if not errors else 'unreviewable','assistance':'rwkv_independent','error':error,'status':state.status.value if state else 'not_started','trace_complete':not errors,'trace_errors':errors,'tool_scope':'production_full','generation_started':sum(e['type']=='model_session_generation_started' for e in records),'protocol_rejections':state.protocol_rejections if state else 0,'actions':[a.to_dict() for a in state.actions.values()] if state else [],'elapsed_seconds':time.monotonic()-started}
 save(output/'RESULT.json',result)
 if state:save(output/'state_snapshot.json',state.to_dict())
 snapshot(workspace,output/'final_workspace');return result
if __name__=='__main__':
 reg=json.loads((D/'REGISTRATION.json').read_text());assert all(v.file_digest(R/p)==s for p,s in reg['source_pins'].items());assert v.file_digest(Path(__file__))==reg['runner_sha256'];load_local_env(R/'.env.local');settings=replace(get_runtime_settings(),base_url=reg['base_url'],model=reg['model_name'],model_sha256=reg['model_sha256'],state_transport='native_required',state_profile_id='zero',state_profile_sha256='0'*64,tool_disclosure_mode='full',return_token_ids=True,read_timeout_seconds=180)
 results=[]
 for job in json.loads((D/'JOBS.json').read_text()):
  result=run(job,settings);results.append(result);save(D/'RESULTS.json',results);print(result['id'],result['termination'],result['generation_started'],flush=True)

